sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {


    try {

        // ================================
        // 1. FETCH QUOTA
        // ================================
        var quotaGR = new GlideRecord('x_ctans_incentnow_quota');

        if (!quotaGR.get(current.quota)) {
            return;
        }

        var quotaStatus = quotaGR.getValue('status');

        // ================================
        // 2. BLOCK NON-ACTIVE QUOTA
        // ================================
        if (quotaStatus != 'active') {

            gs.addErrorMessage(
                "Only ACTIVE quotas can be assigned to users. " +
                "Please activate the quota before assignment."
            );

            current.setAbortAction(true);
            return;
        }

        // ============================================================
        // 1. BASIC VALIDATION
        // ============================================================

        var planAssignmentSysId = current.getValue('plan_assignment');

        var lookupRuleSysId = current.getValue('lookup_rule');

        var quotaSysId = current.getValue('quota');

        if (!planAssignmentSysId || !lookupRuleSysId || !quotaSysId) {
            return;
        }


        // ============================================================
        // 2. VALIDATE LOOKUP RULE BELONGS TO SELECTED PLAN
        // ============================================================

        var planAssignmentGR = new GlideRecordSecure( 'x_ctans_incentnow_plan_users' );

        if (!planAssignmentGR.get(planAssignmentSysId)) {

            gs.addErrorMessage('The selected Plan Assignment is invalid.' );

            current.setAbortAction(true);
            return;
        }


        var planSysId =  planAssignmentGR.getValue('x_ctans_incentnow_plan');

        if (!planSysId) {

            gs.addErrorMessage('The selected Plan Assignment does not have a Plan.');

            current.setAbortAction(true);
            return;
        }


        var lookupRuleGR = new GlideRecordSecure( 'x_ctans_incentnow_lookup_rule');

        if (!lookupRuleGR.get(lookupRuleSysId)) {

            gs.addErrorMessage('The selected Attainment Lookup Rule is invalid.' );
            current.setAbortAction(true);
            return;
        }


        // Lookup Rule must belong to selected Plan
        if ( lookupRuleGR.getValue('plan') != planSysId) {

            gs.addErrorMessage('The selected Attainment Lookup Rule does not belong ' + 'to the Plan associated with this Plan Assignment.');

            current.setAbortAction(true);
            return;
        }


        // Lookup Rule must be quota attainment type
        if (lookupRuleGR.getValue('rule_type') !='quota_attainment') {

            gs.addErrorMessage('Only Quota Attainment Lookup Rules can be mapped ' +'to a Quota Assignment.'
            );

            current.setAbortAction(true);
            return;
        }


        // ============================================================
        // 3. PREVENT DUPLICATE LOOKUP RULE MAPPING
        // ============================================================

        var duplicateGR =
            new GlideRecordSecure( 'x_ctans_incentnow_user_quota_assignment');

        duplicateGR.addQuery( 'plan_assignment', planAssignmentSysId);
        duplicateGR.addQuery('lookup_rule',lookupRuleSysId);


        // Exclude current record during update
        if (!current.isNewRecord()) {

            duplicateGR.addQuery('sys_id','!=',current.getUniqueValue());
        }
        duplicateGR.setLimit(1);
        duplicateGR.query();


        if (duplicateGR.next()) {

            var existingQuota = duplicateGR.getDisplayValue('quota');

            var lookupRule = lookupRuleGR.getDisplayValue();

            gs.addErrorMessage('The Attainment Lookup Rule "' +lookupRule +'" is already mapped to Quota "' + existingQuota +'" for the selected Plan Assignment. ' + 'The same Lookup Rule cannot be mapped more than once.');
            current.setAbortAction(true);
            return;
        }
	}

     catch (e) {

        gs.error( '[IncentIQ Quota Assignment] ' + 'Lookup Rule mapping validation failed. ' + 'Record=' + current.getUniqueValue() + ', Error=' + e.message);
        gs.addErrorMessage('Quota Assignment could not be saved because ' +'the Lookup Rule mapping could not be validated.');
        current.setAbortAction(true);
    }


})(current, previous);
